                                    /** Format: uuid */
                                    observation_id: string;
                                    qty: number;
                                    description: string;
                                    sku_id: string | null;
                                    alias_value: string | null;
                                    in_place_of_line_key: string | null;
                                    pairing_key: string | null;
                                    hold_key: string;
                                    /** @enum {string} */
                                    condition: "good" | "wrong";
